import Foundation

struct Cart {
    var items: [Item] = []

    struct Item {
        let name: String
        let price: Int
        let quantity: Int
    }

    func total() -> Int {
        items.reduce(0) { $0 + $1.price }
    }

    func discounted(by percent: Int) -> Int {
        total() * (100 - percent) / 100
    }

    func first() -> Item {
        items[0]
    }
}
